7	import 'package:mocktail/mocktail.dart';
8	
9	import 'package:cerne/core/di/injection_container.dart';
10	import 'package:cerne/core/failure/failure.dart';
11	import 'package:cerne/core/widgets/confirmation_dialog.dart';
12	import 'package:cerne/features/auth/domain/entities/authenticated_user.dart';
13	import 'package:cerne/features/auth/domain/entities/session_status.dart';
14	import 'package:cerne/features/auth/domain/repositories/auth_repository.dart';
15	import 'package:cerne/features/auth/domain/repositories/session_repository.dart';
16	import 'package:cerne/main.dart';
17	
18	class MockAuthRepository extends Mock implements AuthRepository {}
19	
20	class MockSessionRepository extends Mock implements SessionRepository {}
21	
22	/// Proves the one real production composition root — `CerneApp` resolving
23	/// `sl<AuthCubit>()` and wiring `onAuthenticated` to
24	/// `Navigator.pushReplacement` — actually works end to end (code review of
25	/// story-1-3-account-creation-and-login), and (Story 1.4) that `home`
26	/// actually branches on `SessionRepository.statusStream`'s first emission
27	/// instead of hardcoding `AuthScreen`. Every other test either stops at DI
28	/// registration (`bootstrap_integration_test.dart`) or supplies its own
29	/// `AuthCubit`/`onAuthenticated` (`auth_screen_test.dart`), so neither
30	/// exercises `main.dart`'s own wiring.
31	void main() {
32	  TestWidgetsFlutterBinding.ensureInitialized();
33	
34	  const secureStorageChannel = MethodChannel(
35	    'plugins.it_nomads.com/flutter_secure_storage',
36	  );
37	  final fakeNativeStorage = <String, String>{};
38	
39	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
40	    final args = call.arguments as Map<dynamic, dynamic>;
41	    switch (call.method) {
42	      case 'write':
43	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
44	        return null;
45	      case 'read':
46	        return fakeNativeStorage[args['key'] as String];
47	      case 'delete':
48	        fakeNativeStorage.remove(args['key'] as String);
49	        return null;
50	      case 'containsKey':
51	        return fakeNativeStorage.containsKey(args['key'] as String);
52	      default:
53	        return null;
54	    }
55	  }
56	
57	  setUp(() async {
58	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
59	        .setMockMethodCallHandler(
60	          secureStorageChannel,
61	          handleSecureStorageCall,
62	        );
63	    await resetCoreDependencies();
64	    await setupCoreDependencies();
65	    // `ConfirmationDialog.isOpen` is a static single-overlay guard (shared
66	    // across every instance by design, Story 1.5) — reset it so one test's
67	    // unclosed dialog never leaks into the next.
68	    ConfirmationDialog.isOpen = false;
69	  });
70	
71	  tearDown(() async {
72	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
73	        .setMockMethodCallHandler(secureStorageChannel, null);
74	    fakeNativeStorage.clear();
75	    await resetCoreDependencies();
76	  });
77	
78	  testWidgets(
79	    'CerneApp resolves the real AuthCubit and navigates to the post-auth '
80	    'placeholder once onAuthenticated fires',
81	    (tester) async {
82	      final mockAuthRepository = MockAuthRepository();
83	      when(
84	        () => mockAuthRepository.logIn(
85	          email: any(named: 'email'),
86	          password: any(named: 'password'),
