    testWidgets(
      'after "Entrar novamente" is confirmed, a later rebuild while '
      'statusStream is still expired does not reopen the overlay on top '
      'of the placeholder it already routed to',
      (tester) async {
        final mockSessionRepository = MockSessionRepository();
        final controller = StreamController<SessionStatus>.broadcast();
        addTearDown(controller.close);
        when(() => mockSessionRepository.restoreSession())
            .thenAnswer((_) async => right(unit));
        when(() => mockSessionRepository.statusStream)
            .thenAnswer((_) => controller.stream);

        sl.unregister<SessionRepository>();
        sl.registerLazySingleton<SessionRepository>(
          () => mockSessionRepository,
        );

        await tester.pumpWidget(const CerneApp());
        controller.add(SessionStatus.authenticated);
        await tester.pumpAndSettle();

        controller.add(SessionStatus.expired);
        await tester.pumpAndSettle();

        await tester.tap(find.text('Entrar novamente'));
        await tester.pumpAndSettle();
        expect(find.text('Biometria'), findsOneWidget);

        // Simulates a rebuild that isn't driven by a new stream event
        // (e.g. a hot reload) while `statusStream`'s cached snapshot is
        // still `expired` — without the overlay's own one-shot-per-episode
        // guard, `StreamBuilder`'s builder re-running would reopen it on
        // top of the placeholder the user already navigated to.
        await tester.binding.reassembleApplication();
        await tester.pumpAndSettle();

        expect(find.text('Sessão expirada'), findsNothing);
        expect(find.text('Biometria'), findsOneWidget);
      },
    );
  });
}

